def update_in(coll, path, update, default=None):
    """Creates a copy of coll with a value updated at path."""
    if not path:
        return coll  # Top-level empty path: return unchanged
    elif isinstance(coll, list):
        copy = coll[:]
        # NOTE: there is no auto-vivication for lists
        _update_in_recursive(copy, path[0], path[1:], update, default)
        return copy
    else:
        copy = coll.copy()
        _update_in_recursive_or_set(copy, path[0], path[1:], update, default)
        return copy


def _update_in_recursive(coll, key, path, update, default):
    """Internal helper for recursive update_in calls."""
    if not path:
        coll[key] = update(coll.get(key))
    elif isinstance(coll.get(key), list):
        current = coll.get(key, [])
        if key not in coll:
            coll[key] = []
        copy = coll[key][:]
        copy[path[0]] = _update_in_recursive_safe(current[path[0]], path[1:], update, default)
        coll[key] = copy
    else:
        _update_in_recursive_or_set(coll, key, path, update, default)


def _update_in_recursive_or_set(coll, key, path, update, default):
    """Internal helper for dict-based recursive update_in calls."""
    if not path:
        coll[key] = update(coll.get(key, {} if default is None else default))
    elif isinstance(coll.get(key), list):
        if key not in coll:
            coll[key] = []
        copy = coll[key][:]
        copy[path[0]] = _update_in_recursive_safe(coll[key][path[0]], path[1:], update, default)
        coll[key] = copy
    else:
        current_default = {} if len(path) > 1 else default
        val = coll.get(key, current_default)
        if key not in coll:
            coll[key] = val if isinstance(val, (dict, list)) else current_default
        if isinstance(val, list):
            copy = val[:]
            copy[path[0]] = _update_in_recursive_safe(val[path[0]], path[1:], update, default)
            coll[key] = copy
        else:
            _update_in_recursive_or_set(coll[key], path[0], path[1:], update, default)


def _update_in_recursive_safe(coll, path, update, default):
    """Simpler version for cases where we already have the value."""
    if not path:
        return update(coll)
    elif isinstance(coll, list):
        copy = coll[:]
        copy[path[0]] = _update_in_recursive_safe(copy[path[0]], path[1:], update, default)
        return copy
    else:
        copy = coll.copy()
        current_default = {} if len(path) > 1 else default
        copy[path[0]] = _update_in_recursive_safe(copy.get(path[0], current_default), path[1:], update, default)
        return copy

